def transform(grid):
    """Paint a 3x3 halo of color 1 around each 2 inside a 4-connected 3-object.

    Markers outside the colored objects are distractors; object cells and zeros
    remain unchanged, and 2 markers are preserved.
    """
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            boxes.append((min(y for y, x in cells), max(y for y, x in cells),
                          min(x for y, x in cells), max(x for y, x in cells)))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                       for r0, r1, c0, c1 in boxes):
                for rr in range(max(0, r - 1), min(h, r + 2)):
                    for cc in range(max(0, c - 1), min(w, c + 2)):
                        if grid[rr][cc] != 2:
                            out[rr][cc] = 1
    return out
